673					t.Fatal(err)
674				}
675				if err := os.WriteFile(manifest, manifestContent, 0o644); err != nil {
676					t.Fatal(err)
677				}
678				pinned := time.Date(2003, time.April, 5, 6, 7, 8, 0, time.UTC)
679				if err := os.Chtimes(registry, pinned, pinned); err != nil {
680					t.Fatal(err)
681				}
682	
683				assertBlocked := func(err error, stdout *bytes.Buffer) {
684					t.Helper()
685					if err == nil {
686						t.Fatal("malformed registry must be rejected")
687					}
688					msg := err.Error()
689					for _, want := range []string{registry, tc.pos, tc.field} {
690						if !strings.Contains(msg, want) {
691							t.Fatalf("error must mention %q: %v", want, msg)
692						}
693					}
694					if tc.batch != "" && !strings.Contains(msg, tc.batch) {
695						t.Fatalf("error must cite batch %q: %v", tc.batch, msg)
696					}
697					if tc.batch == "" && strings.Contains(msg, "�") {
698						t.Fatalf("error must not cite a substituted id: %v", msg)
699					}
700					if stdout.Len() != 0 {
701						t.Fatalf("stdout must stay empty: %q", stdout.String())
702					}
703				}
704	
705				var stdout bytes.Buffer
706				err := runBatchRegister([]string{
707					"--registry", registry, "--batch", "NEW", "--product", "P",
708					"--quantity", "1", "--unit", "kg",
709				}, &stdout)
710				assertBlocked(err, &stdout)
711	
712				stdout.Reset()
713				err = runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout)
714				assertBlocked(err, &stdout)
715	
716				after, rerr := os.ReadFile(registry)
717				if rerr != nil || !bytes.Equal(after, tc.content) {
718					t.Fatalf("registry bytes changed: %q", after)
719				}
720				info, serr := os.Stat(registry)
721				if serr != nil || !info.ModTime().Equal(pinned) {
722					t.Fatalf("registry mtime changed: %v", serr)
723				}
724				mAfter, merr := os.ReadFile(manifest)
725				if merr != nil || !bytes.Equal(mAfter, manifestContent) {
726					t.Fatal("manifest was modified")
727				}
728			})
729		}
730	}
731	
732	// Valid Unicode — CJK, emoji and a genuine U+FFFD — works end to end, and a
733	// JSON escape means the same text as the directly written character.
734	func TestUnicodeRoundTripsThroughBothCommands(t *testing.T) {
735		dir := t.TempDir()
736		registry := filepath.Join(dir, "reg.json")
737	
738		var stdout bytes.Buffer
739		if err := runBatchRegister([]string{
740			"--registry", registry, "--batch", " 批次-1 ", "--product", "产品😀",
741			"--quantity", "7", "--unit", "千克",
742		}, &stdout); err != nil {
743			t.Fatal(err)
744		}
745		if !strings.Contains(stdout.String(), `"status":"created"`) ||
746			!strings.Contains(stdout.String(), `"batch":"批次-1"`) {
747			t.Fatalf("unexpected output: %q", stdout.String())
748		}
749	
750		// The same batch via a JSON \uXXXX escape pair for the emoji must be a
751		// duplicate, while a direct genuine U+FFFD registers a distinct batch.
752		manifest := filepath.Join(dir, "in.json")
753		writeFile(t, manifest, `[
754			{"batch":"批次-1","product":"产品😀","quantity":7,"unit":"千克"},
755			{"batch":"B-FFFD","product":"P�","quantity":1,"unit":"kg"}
756		]`)
757		stdout.Reset()
758		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
759			t.Fatal(err)
760		}
761		var out importOutput
762		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
763			t.Fatal(err)
764		}
765		if len(out.Results) != 2 ||
766			out.Results[0].Status != "duplicate" || out.Results[0].Product != "产品😀" ||
767			out.Results[1].Status != "created" || out.Results[1].Product != "P�" {
768			t.Fatalf("unexpected results: %s", stdout.String())
769		}
770	
771		// Re-registering the genuine U+FFFD batch directly is a duplicate, and a
772		// malformed byte in a different flag is still refused.
773		stdout.Reset()
774		if err := runBatchRegister([]string{
775			"--registry", registry, "--batch", "B-FFFD", "--product", "P�",
776			"--quantity", "1", "--unit", "kg",
777		}, &stdout); err != nil {
778			t.Fatalf("genuine U+FFFD must stay usable: %v", err)
779		}
780		if !strings.Contains(stdout.String(), `"status":"duplicate"`) {
781			t.Fatalf("expected duplicate: %q", stdout.String())
782		}
783	}
784	
785	// registerCLI runs one batch-register invocation and returns its stdout.
786	func registerCLI(t *testing.T, registry, batch, product, quantity, unit string) (string, error) {
787		t.Helper()
788		var stdout bytes.Buffer
789		err := runBatchRegister([]string{
790			"--registry", registry,
791			"--batch", batch,
792			"--product", product,
793			"--quantity", quantity,
794			"--unit", unit,
795		}, &stdout)
796		return stdout.String(), err
797	}
798	
799	type registerResult struct {
800		Batch    string `json:"batch"`
801		Product  string `json:"product"`
802		Quantity int64  `json:"quantity"`
803		Unit     string `json:"unit"`
804		Status   string `json:"status"`
805	}
806	
807	// decodeRegisterResult parses stdout as exactly one JSON object carrying
808	// exactly the four record fields plus status — nothing before, after or
809	// beyond it, and no extra or missing members.
810	func decodeRegisterResult(t *testing.T, stdout string) registerResult {
811		t.Helper()
812		dec := json.NewDecoder(strings.NewReader(stdout))
813		var keys map[string]json.RawMessage
814		if err := dec.Decode(&keys); err != nil {
815			t.Fatalf("stdout is not a JSON object: %v (%q)", err, stdout)
816		}
817		if err := dec.Decode(&struct{}{}); err != io.EOF {
818			t.Fatalf("stdout must hold exactly one JSON object, got %q", stdout)
819		}
820		for _, want := range []string{"batch", "product", "quantity", "unit", "status"} {
821			if _, ok := keys[want]; !ok {
822				t.Fatalf("result object is missing field %q: %q", want, stdout)
823			}
824			delete(keys, want)
825		}
826		if len(keys) != 0 {
827			t.Fatalf("result object carries unexpected field(s): %q", stdout)
828		}
829		var res registerResult
830		if err := json.Unmarshal([]byte(stdout), &res); err != nil {
831			t.Fatalf("result object does not match the record shape: %v (%q)", err, stdout)
832		}
833		return res
834	}
835	
836	// readStoredBatches decodes the registry file into its records, in file order.
837	func readStoredBatches(t *testing.T, path string) []registerResult {
838		t.Helper()
839		data, err := os.ReadFile(path)
840		if err != nil {
841			t.Fatal(err)
842		}
843		var stored struct {
844			Version int              `json:"version"`
845			Batches []registerResult `json:"batches"`
846		}
847		if err := json.Unmarshal(data, &stored); err != nil {
848			t.Fatalf("registry file does not decode: %v (%s)", err, data)
849		}
850		if stored.Version != 1 {
851			t.Fatalf("registry version = %d, want 1", stored.Version)
852		}
853		return stored.Batches
854	}
855	
856	// pinRegistry reads the registry and pins a distinctive past mtime so any
857	// rewrite — even one reproducing identical bytes — is observable.
858	func pinRegistry(t *testing.T, path string) (content []byte, pinned time.Time) {
859		t.Helper()
860		pinned = time.Date(2004, time.May, 6, 7, 8, 9, 0, time.UTC)
861		if err := os.Chtimes(path, pinned, pinned); err != nil {
862			t.Fatal(err)
863		}
864		content, err := os.ReadFile(path)
865		if err != nil {
866			t.Fatal(err)
867		}
868		return content, pinned
869	}
870	
871	// assertRegistryUntouched fails if the file's bytes or mtime differ from the
872	// pinned snapshot.
873	func assertRegistryUntouched(t *testing.T, path string, content []byte, pinned time.Time) {
874		t.Helper()
875		after, err := os.ReadFile(path)
876		if err != nil {
877			t.Fatal(err)
878		}
879		if !bytes.Equal(after, content) {
880			t.Fatalf("registry bytes changed:\nbefore: %s\nafter:  %s", content, after)
881		}
882		info, err := os.Stat(path)
883		if err != nil {
884			t.Fatal(err)
885		}
886		if !info.ModTime().Equal(pinned) {
887			t.Fatalf("registry mtime changed: got %v, want %v", info.ModTime(), pinned)
888		}
889	}
890	
891	// A first registration returns "created"; re-submitting the same record —
892	// spelled with padding and leading zeros that normalize away — confirms the
893	// stored record as "duplicate", echoing the registered four fields as the
894	// only JSON object on stdout. The file keeps exactly its earlier records,
895	// the other batch's fields and position included, and neither its bytes nor
896	// its mtime move during the confirmation.
897	func TestBatchRegisterCLIDuplicateConfirm(t *testing.T) {
898		dir := t.TempDir()
899		registry := filepath.Join(dir, "reg.json")
900	
901		stdout, err := registerCLI(t, registry, "B-000", "P-0", "5", "box")
902		if err != nil {
903			t.Fatal(err)
904		}
905		if res := decodeRegisterResult(t, stdout); res.Status != "created" {
906			t.Fatalf("first registration of B-000 = %+v, want created", res)
907		}
908	
909		stdout, err = registerCLI(t, registry, " B-001 ", " P-7 ", "000120", " kg ")
910		if err != nil {
911			t.Fatal(err)
912		}
913		created := decodeRegisterResult(t, stdout)
914		want := registerResult{Batch: "B-001", Product: "P-7", Quantity: 120, Unit: "kg", Status: "created"}
915		if created != want {
916			t.Fatalf("first registration = %+v, want %+v", created, want)
917		}
918	
919		content, pinned := pinRegistry(t, registry)
920	
921		// The same record with the padding and leading zeros already removed is
922		// the identical effective value: a duplicate, not a new record.
923		stdout, err = registerCLI(t, registry, "B-001", "P-7", "120", "kg")
924		if err != nil {
925			t.Fatalf("identical re-registration must succeed: %v", err)
926		}
927		dup := decodeRegisterResult(t, stdout)
928		want.Status = "duplicate"
929		if dup != want {
930			t.Fatalf("duplicate confirmation = %+v, want %+v", dup, want)
931		}
932		assertRegistryUntouched(t, registry, content, pinned)
933	
934		// Still exactly one record per batch, the other batch first and unchanged.
935		batches := readStoredBatches(t, registry)
936		if len(batches) != 2 {
937			t.Fatalf("registry holds %d records, want 2: %v", len(batches), batches)
938		}
939		if batches[0] != (registerResult{Batch: "B-000", Product: "P-0", Quantity: 5, Unit: "box"}) {
940			t.Fatalf("other batch's record changed: %+v", batches[0])
941		}
942		if batches[1] != (registerResult{Batch: "B-001", Product: "P-7", Quantity: 120, Unit: "kg"}) {
943			t.Fatalf("stored record changed: %+v", batches[1])
944		}
945	}
946	
947	// A registry file whose layout differs from what Save would write — compact,
948	// members in another order — is still not re-saved to confirm a duplicate:
949	// bytes and mtime stay exactly as they were.
950	func TestBatchRegisterCLIDuplicateKeepsForeignFileLayout(t *testing.T) {
951		dir := t.TempDir()
952		registry := filepath.Join(dir, "reg.json")
953		original := `{"batches":[{"unit":"kg","quantity":120,"product":"P-7","batch":"B-001"}],"version":1}`
954		writeFile(t, registry, original)
955		content, pinned := pinRegistry(t, registry)
956	
957		stdout, err := registerCLI(t, registry, "B-001", "P-7", "120", "kg")
958		if err != nil {
959			t.Fatalf("duplicate confirmation must succeed: %v", err)
960		}
961		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" {
962			t.Fatalf("got %+v, want duplicate", res)
963		}
964		assertRegistryUntouched(t, registry, content, pinned)
965		if after, _ := os.ReadFile(registry); string(after) != original {
966			t.Fatalf("foreign layout was rewritten:\nbefore: %s\nafter:  %s", original, after)
967		}
968	}
969	
970	// Re-registering a batch id with any differing field fails: stdout stays
971	// empty, the error names the batch and every mismatching field — never just
972	// one of several — and the file keeps its bytes and mtime. Interior
973	// whitespace and casing are significant, so "p-7" and "k g" are conflicts,
974	// not duplicates.
975	func TestBatchRegisterCLIConflictReportsAllDifferingFields(t *testing.T) {
976		cases := map[string]struct {
977			product  string
978			quantity string
979			unit     string
980			fields   []string
981		}{
982			"product casing differs":      {"p-7", "120", "kg", []string{"product"}},
983			"unit interior space differs": {"P-7", "120", "k g", []string{"unit"}},
984			"quantity differs":            {"P-7", "121", "kg", []string{"quantity"}},
985			"all three differ":            {"P-8", "121", "g", []string{"product", "quantity", "unit"}},
986		}
987		for name, tc := range cases {
988			t.Run(name, func(t *testing.T) {
989				dir := t.TempDir()
990				registry := filepath.Join(dir, "reg.json")
991				writeFile(t, registry, `{"version":1,"batches":[`+
992					`{"batch":"B-000","product":"P-0","quantity":5,"unit":"box"},`+
993					`{"batch":"B-001","product":"P-7","quantity":120,"unit":"kg"}]}`)
994				content, pinned := pinRegistry(t, registry)
995	
996				stdout, err := registerCLI(t, registry, "B-001", tc.product, tc.quantity, tc.unit)
997				if err == nil {
998					t.Fatal("a conflicting re-registration must fail")
999				}
1000				if stdout != "" {
1001					t.Fatalf("stdout must stay empty on conflict, got %q", stdout)
1002				}
1003				msg := err.Error()
1004				if !strings.Contains(msg, strconv.Quote("B-001")) {
1005					t.Fatalf("error must name the batch: %v", msg)
1006				}
1007				for _, field := range tc.fields {
1008					if !strings.Contains(msg, field) {
1009						t.Fatalf("error must report differing field %q: %v", field, msg)
1010					}
1011				}
1012				assertRegistryUntouched(t, registry, content, pinned)
1013	
1014				batches := readStoredBatches(t, registry)
1015				if len(batches) != 2 || batches[1].Product != "P-7" ||
1016					batches[1].Quantity != 120 || batches[1].Unit != "kg" {
1017					t.Fatalf("the conflict must not overwrite the stored record: %v", batches)
1018				}
1019			})
1020		}
1021	}
1022	
1023	// Batch ids compare byte for byte: "b-001" is a different id from "B-001" and
1024	// registers as its own record, after which it confirms duplicates of its own.
1025	func TestBatchRegisterCLIBatchIDCaseSensitive(t *testing.T) {
1026		dir := t.TempDir()
1027		registry := filepath.Join(dir, "reg.json")
1028	
1029		if _, err := registerCLI(t, registry, "B-001", "P-7", "120", "kg"); err != nil {
1030			t.Fatal(err)
1031		}
1032		stdout, err := registerCLI(t, registry, "b-001", "P-7", "120", "kg")
1033		if err != nil {
1034			t.Fatalf("a case-distinct batch id must register: %v", err)
1035		}
1036		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Batch != "b-001" {
1037			t.Fatalf("got %+v, want created b-001", res)
1038		}
1039	
1040		batches := readStoredBatches(t, registry)
1041		if len(batches) != 2 || batches[0].Batch != "B-001" || batches[1].Batch != "b-001" {
1042			t.Fatalf("want B-001 and b-001 as separate records in order, got %v", batches)
1043		}
1044	
1045		stdout, err = registerCLI(t, registry, "b-001", "P-7", "120", "kg")
1046		if err != nil {
1047			t.Fatal(err)
1048		}
1049		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" {
1050			t.Fatalf("got %+v, want duplicate", res)
1051		}
1052		if batches := readStoredBatches(t, registry); len(batches) != 2 {
1053			t.Fatalf("duplicate confirmation added a record: %v", batches)
1054		}
1055	}
1056	
1057	// Quantities compare as integers right up to the int64 ceiling: MaxQuantity
1058	// registers and confirms as a duplicate, one less conflicts on quantity, and
1059	// anything above the ceiling is rejected as an illegal --quantity value —
1060	// never a created or duplicate result.
1061	func TestBatchRegisterCLIQuantityBoundaries(t *testing.T) {
1062		dir := t.TempDir()
1063		registry := filepath.Join(dir, "reg.json")
1064		const max = "9223372036854775807"
1065	
1066		stdout, err := registerCLI(t, registry, "B-MAX", "P-7", max, "kg")
1067		if err != nil {
1068			t.Fatalf("the maximum quantity must register: %v", err)
1069		}
1070		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Quantity != 9223372036854775807 {
1071			t.Fatalf("got %+v, want created with quantity 9223372036854775807", res)
1072		}
1073	
1074		stdout, err = registerCLI(t, registry, "B-MAX", "P-7", max, "kg")
1075		if err != nil {
1076			t.Fatalf("the maximum quantity must confirm as duplicate: %v", err)
1077		}
1078		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" || res.Quantity != 9223372036854775807 {
1079			t.Fatalf("got %+v, want duplicate with quantity 9223372036854775807", res)
1080		}
1081	
1082		content, pinned := pinRegistry(t, registry)
1083	
1084		stdout, err = registerCLI(t, registry, "B-MAX", "P-7", "9223372036854775806", "kg")
1085		if err == nil {
1086			t.Fatal("one less than the stored quantity must conflict, not confirm")
1087		}
1088		if stdout != "" {
1089			t.Fatalf("stdout must stay empty on conflict, got %q", stdout)
1090		}
1091		if msg := err.Error(); !strings.Contains(msg, strconv.Quote("B-MAX")) || !strings.Contains(msg, "quantity") {
1092			t.Fatalf("error must name the batch and the quantity field: %v", msg)
1093		}
1094		assertRegistryUntouched(t, registry, content, pinned)
1095	
1096		stdout, err = registerCLI(t, registry, "B-OVER", "P-7", "9223372036854775808", "kg")
1097		if err == nil {
1098			t.Fatal("a quantity above the maximum must be rejected")
1099		}
1100		if stdout != "" {
1101			t.Fatalf("stdout must stay empty on invalid input, got %q", stdout)
1102		}
1103		if msg := err.Error(); !strings.Contains(msg, "--quantity") || !strings.Contains(msg, max) {
1104			t.Fatalf("error must reject --quantity against the maximum %s: %v", max, msg)
1105		}
1106		assertRegistryUntouched(t, registry, content, pinned)
1107	
1108		if batches := readStoredBatches(t, registry); len(batches) != 1 || batches[0].Quantity != 9223372036854775807 {
1109			t.Fatalf("failures must not add or alter records: %v", batches)
1110		}
1111	}
